program='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = set(v for row in grid for v in row if v != bg)
    for color in colors:
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color:
                    continue
                for dr, dc in ((1, 1), (1, -1)):
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                        continue
                    # Continue each diagonal pair in both directions until an obstacle or edge.
                    for sr, sc, rr, cc in ((r, c, -dr, -dc), (nr, nc, dr, dc)):
                        rr0, cc0 = sr + rr, sc + cc
                        while 0 <= rr0 < h and 0 <= cc0 < w and grid[rr0][cc0] == bg:
                            out[rr0][cc0] = color
                            rr0 += rr
                            cc0 += cc
    return out
'''
